package dev.industrialtechnology.automation;
import org.junit.Test;import static org.junit.Assert.*;import com.google.gson.*;import java.util.*;
public class AutomationReferenceTest {
    @Test public void sharedReferenceCoversEveryConditionAndAction(){Set<String> conditions=new HashSet<String>(),actions=new HashSet<String>();for(JsonElement e:AutomationReference.data().getAsJsonArray("conditions"))conditions.add(e.getAsJsonObject().get("id").getAsString());for(JsonElement e:AutomationReference.data().getAsJsonArray("actions"))actions.add(e.getAsJsonObject().get("id").getAsString());for(ScriptRule.Kind k:ScriptRule.Kind.values())assertTrue(k.name(),conditions.remove(k.name()));for(ScriptRule.Action a:ScriptRule.Action.values())assertTrue(a.name(),actions.remove(a.name()));assertTrue(conditions.isEmpty());assertTrue(actions.isEmpty());}
    @Test public void everyBookHelpAndMarkdownExampleUsesRealGrammar()throws Exception{ScriptCompiler.Resolver r=new ScriptCompiler.Resolver(){public String item(String id){return id;}public String fluid(String id){return id;}public UUID control(String name){return UUID.nameUUIDFromBytes(name.getBytes(java.nio.charset.StandardCharsets.UTF_8));}};int count=0;for(AutomationReference.Section s:AutomationReference.sections())if(!s.example.isEmpty()){assertFalse(ScriptCompiler.compile(s.example,4096,r).isEmpty());count++;}assertTrue(count>=20);}
}
